import{_ as t,o,c as a,a0 as n}from"./chunks/framework.ysVzM4be.js";const s="/my-little-software-factory/assets/decision-modal.C_L3XhML.png",g=JSON.parse('{"title":"Modals","description":"The decision modal, the missing modal, and the leftover environment action keys.","frontmatter":{"title":"Modals","description":"The decision modal, the missing modal, and the leftover environment action keys."},"headers":[],"relativePath":"operation/modals.md","filePath":"operation/modals.md"}'),r={name:"operation/modals.md"};function d(i,e,h,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="modals" tabindex="-1">Modals <a class="header-anchor" href="#modals" aria-label="Permalink to &quot;Modals&quot;">​</a></h1><h2 id="decision-modal" tabindex="-1">Decision modal <a class="header-anchor" href="#decision-modal" aria-label="Permalink to &quot;Decision modal&quot;">​</a></h2><p><img src="'+s+`" alt="The decision modal on an awaiting ticket: the turn log of the settled
turn above the choice rows"></p><p>Enter on an <code>awaiting</code> ticket opens the decision modal: a near-fullscreen modal that pops in over the app with a short fade and grow, one cell of margin on every side. In auto mode, and on an auto-close task type, the factory decides the ticket itself: Enter only reports that, and the modal stays closed. Its border reads <code>Decision: &lt;ticket title&gt;</code>, and the first row under the border names the context: repository, task type, agent, completion time.</p><p>The body is the turn log of the settled turn, in order. The agent&#39;s text blocks carry light markdown dressing: headings render bright without their hashes, bold renders bright, code renders dim, lists keep their markers and indent per level, links keep their label. Each tool call is one dim note, <code>▸ name: target</code>; a failed call wears the warning color. The agent&#39;s thinking text is not shown. The log comes from the agent&#39;s session record (ADR 0008); when no session is known, the terminal capture stands in. The modal opens at the bottom, where the agent&#39;s conclusion is, and a proportional scrollbar shows the position when the log is longer than the window.</p><p>The modal offers the choices the state allows. <code>Up</code> and <code>Down</code> move between the choice rows; <code>j</code> and <code>k</code> scroll the turn log one row, with the page and jump keys as aliases. <code>Enter</code> chooses the selected row, <code>e</code> edits the selected Handoff row&#39;s settings before it starts, and <code>Esc</code> closes the modal: nothing runs, and the ticket stays awaiting. The shared Action bar at the terminal bottom names these controls. The first row, &quot;Close&quot;, ends the work cycle: the ticket returns to open with its cycle number incremented, and the handoff&#39;s environment is closed without touching the git branch, so pushed work and pull requests survive: a worktree handoff loses its worktree checkout and its herdr workspace, a live worktree handoff loses its tab. The second row, &quot;Goto&quot;, focuses the agent&#39;s pane so the operator can steer it; the ticket returns to <code>running</code>. Goto is a state move, not a completion decision, so the trace does not record it: the turn&#39;s pending trace stays pending, and the next settle refreshes it with the agent&#39;s new last message. Then one &quot;Handoff: <code>&lt;task type&gt;</code>&quot; row per outgoing workflow edge the completed task type has, in config order: an edge naming several targets offers one row per target, and two edges to the same target keep both rows, so every edge stays reachable. The row&#39;s detail shows the Agent the arriving handoff resolves to (the edge&#39;s pin, else the target Task profile&#39;s agent, else <code>default-agent</code>), and the edge&#39;s pinned environment when the edge defines one. Choosing a row hands the ticket off again with that target task type. <code>e</code> on such a row opens the override panel on the choice the edge resolved, so the operator can change the agent, environment, Model, or Thinking for this one handoff before it starts; the override outranks the edge pin, the Task profile, and the defaults. Moving that panel to another Task type re-derives the rows the operator never touched from the type&#39;s own profile, so the route&#39;s Agent pin goes with the target the edge named. <code>Esc</code> there closes the panel back to the decision: nothing is claimed and nothing runs. Enter on an awaiting ticket keeps the direct route, so a route the operator wants unchanged stays one press. The row&#39;s &quot;handed-off&quot; decision lands on the turn&#39;s trace only when the routed handoff settles with the agent started; a failed route leaves the trace pending, so Close and Goto keep working on the awaiting ticket. The automatic route decides the same way: its <code>auto-handed-off</code> record waits for the same start.</p><h2 id="missing-modal" tabindex="-1">Missing modal <a class="header-anchor" href="#missing-modal" aria-label="Permalink to &quot;Missing modal&quot;">​</a></h2><p>Enter on a ticket whose agent is missing opens the missing modal. It shows the badge fact and the handoff count, and it offers &quot;Restart&quot; and &quot;Abandon&quot;. <code>Up</code> and <code>Down</code> move between the choice rows, <code>j</code> and <code>k</code> scroll its message, <code>Enter</code> chooses the selected row, and <code>Esc</code> closes the modal: nothing runs, and the badge stays. The shared Action bar at the terminal bottom names these controls. &quot;Restart&quot; hands the ticket off again with the same choices, in the workspace the handoff recorded, and the last completion&#39;s message as the previous message. &quot;Abandon&quot; ends the work cycle: the ticket returns to open with its cycle number incremented, the handoff&#39;s environment is closed, and the missing badge clears.</p><h2 id="leftover-environment-action-keys" tabindex="-1">Leftover environment action keys <a class="header-anchor" href="#leftover-environment-action-keys" aria-label="Permalink to &quot;Leftover environment action keys&quot;">​</a></h2><p><code>w</code> on a ticket wearing the <code>leftover</code> marker opens the clear panel.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Up</code> / <code>Down</code></td><td>Move between the choice rows</td></tr><tr><td><code>Enter</code></td><td>Choose the selected row</td></tr><tr><td><code>Esc</code></td><td>Close the panel: nothing runs, the leftover stays recorded</td></tr></tbody></table><p>&quot;Retry&quot; runs the Close cleanup again. &quot;Force&quot; is a row only where the leftover is a checkout, because a forced removal discards uncommitted work and stops the agents in the workspace: the control plane never reaches for it by itself. A removal that succeeds clears the leftover; a removal that fails records the reason again. The git branch survives either way.</p><p>A clear ends the environments its cleanup reaches: a workspace removal clears the leftovers that named that workspace, a tab close the one that named that tab, and a cleanup that ran no command only the fact of its own cycle. Facts outside that reach stand. Because a cleanup reaches an environment, it refuses a leftover naming the ticket&#39;s own live agent: the workspace, tab, or pane that agent runs on, and the Message line names what it refused. Close that work cycle first, and its own cleanup ends the leftover with it. A clear refused because a handoff or another clear is already at herdr reports that too, and the operator presses <code>w</code> again. A clear holds the handoff seat while it runs, and a handoff the operator starts beside one waits for it, so herdr never builds an agent in a workspace it is taking away.</p>`,13)])])}const f=t(r,[["render",d]]);export{g as __pageData,f as default};
